import logging
import re
from taf.sbts.oam.coam.admin.exceptions import DataNotAvailable
from taf.rfrl.bts.devices.exceptions import IncorrectStatus, IncorrectStatuses


def verify_statuses(expected_statuses, received_statuses, device=None):
    """
    Verify statuses are as expected.

    :param expected_statuses:   dict with expected statuses.
    :param received_statuses:   dict with received statuses.
    :param device:              str, eg dist_name or any info related to device or its type
    :return:                    None
    :raise:                     DataNotAvailable
    """

    logging.debug("Expected statuses: {}".format(expected_statuses))
    logging.debug("Received statuses: {}".format(received_statuses))

    _re_pattern_class = type(re.compile(''))
    all_incorrect_statuses = []
    try:
        for param_name in expected_statuses:
            append_exception_flag = False
            expected_status = expected_statuses[param_name]
            if isinstance(expected_status, _re_pattern_class):
                if not expected_status.search(received_statuses[param_name].lower()):
                    append_exception_flag = True
            else:
                if expected_statuses[param_name].lower() != received_statuses[param_name].lower():
                    append_exception_flag = True

            if append_exception_flag is True:
                all_incorrect_statuses.append(
                    IncorrectStatus(param_name=param_name,
                                    expected_value=expected_status,
                                    received_value=received_statuses[param_name])
                )
    except KeyError as e:
        raise DataNotAvailable("Cannot get expected status info: {}".format(repr(e)))

    if all_incorrect_statuses:
        raise IncorrectStatuses(incorrect_statuses=all_incorrect_statuses, device=device)


def unify_statuses(statuses, required_keys=None):
    """
    Unify keys and status values to CNI-61110 changes.
    .. note::
        This function modifies the input dictionary `statuses` directly

    :param statuses: dict of statuses
    :param required_keys: list of required keys
    :return:
    """
    logging.debug("Statuses before change: {}".format(statuses))

    if required_keys:
        for req_key in required_keys:
            if req_key not in statuses.keys():
                if req_key == 'availabilityStatus':
                    statuses[req_key] = 'Online'
                else:
                    statuses[req_key] = None
            if req_key == 'availabilityStatus' and statuses[req_key] is None:
                statuses[req_key] = 'Online'
    for status in statuses:
        if statuses[status] is not None:
            statuses[status] = statuses[status].lower()
        if status != 'proceduralStatus' and statuses[status] is not None:
            statuses[status] = statuses[status].replace(' ', '')

    logging.debug("Statuses after: {}".format(statuses))

    return statuses
